+    assert!(h.undo(&world));
+    h.execute(&world, GenerateOperation::new(&world, "Thread1").expect("generate"));
+    assert_eq!(thread_order(&cached(&world, "Thread1")), vec![-40.0, 0.0, 40.0], "undo restores the list order");
